export default async function EnrollmentPage({
  searchParams,
}: {
  searchParams: Promise<{

export function EnrollmentPage({
  data,
  sp: searchParams,
}: {
  data: EnrollmentListData;
  sp: {

    from?: string;
  }>;
}) {

    from?: string;
  };
}) {

const progressHistory =
  view === "stats"
    ? loadOpsHistory(user.tenantId, progressPeriod, today).catch((error: unknown) => {
        reportWarning("상담 진행 기록 조회 실패", { scope: "enrollment.progressHistory", cause: error instanceof Error ? error.message : String(error) });
        return null;
      })
    : Promise.resolve(null);

const intakePromise =
  view === "stats"
    ? getTenantSettings()
        .then(async (settings) => ({
          groups: intakeGroupMeta(settings.operations.subjects),
          trend: await loadIntakeTrend(intakePeriod, settings.operations.subjects, today).catch((error: unknown) => {
            reportWarning("신규 문의 추이 조회 실패", { scope: "enrollment.intakeTrend", cause: error instanceof Error ? error.message : String(error) });
            return null;
          }),
        }))
        .catch(() => null)
    : Promise.resolve(null);

const [kanbanItems, tablePage, headerCounts, statsYears, _unused, schoolPrefs, consultants, minYear, totalCount] =
  await Promise.all([
    view === "kanban" ? getEnrollmentConsultations(filter) : Promise.resolve(null),
    view === "table" ? getEnrollmentConsultationsPage(filter, page, PAGE_SIZE) : Promise.resolve(null),
    // 헤더 스탯은 페이지가 아니라 **필터 전체** 기준(count만, 행 미수신).
    view === "table" ? getConsultationFilteredCounts(filter) : Promise.resolve(null),
    // 전체 기간이면 데이터가 있는 범위를 훑는다(연도 목록의 최소~최대).
    view === "stats" ? getStatsYears() : Promise.resolve([]),
    Promise.resolve(null), // 자리 유지(아래에서 statsYears를 안 뒤 두 번째 단계로 조회)
    // 학교별 점유율 보기 설정(정렬·필터·기준)은 계정 귀속 — localStorage는 포트 단위라 조용히 리셋된다.
    view === "stats" ? loadSchoolStatsPrefs() : Promise.resolve(null),
    getConsultantOptions(),
    getConsultationMinYear(),
    // 자동 갱신 기준선 — 필터와 무관한 **전체 건수**(head 카운트라 행 미수신). 필터가 걸려 있어도
    // 새 접수가 들어오면 화면을 갱신해야 하므로 필터된 items.length를 기준으로 쓰면 안 된다.
    getConsultationTotalCount(),
  ]);

const [stats, dist, intake, withdrawals] =
  view === "stats"
    ? await Promise.all([
        getEnrollmentStats(statsYear, span),
        // 🔴 상담 분포는 **연도가 적용된다**(재원생 기준이던 때는 연도를 바꿔도 안 변해 화면이 거짓말했다).
        getConsultationDistribution(statsYear, span),
        intakePromise,
        // 관리현황 '등록 후 퇴원' — 퇴원관리·운영실과 같은 퇴원 목록(같은 원본). 기간 첫날부터 오늘까지(보는 해 뒤에 퇴원해도 센다).
        canSeeExits
          ? getWithdrawalsInWindow(`${span.from}-01-01`, today).catch((error: unknown) => {
              reportWarning("관리현황 퇴원 조회 실패", { scope: "enrollment.managementExits", cause: error instanceof Error ? error.message : String(error) });
              return null;
            })
          : Promise.resolve(null),
      ])
    : [null, null, null, null];

const [stats, dist, intake, withdrawals] =
  view === "stats"
    ? [data.stats, data.dist, intakePromise, data.withdrawals]
    : [null, null, null, null];
